package br.com.conectatea.profissional.application; import br.com.conectatea.profissional.domain.TarefaLimpezaArquivo; import br.com.conectatea.profissional.infrastructure.TarefaLimpezaArquivoRepository; import java.io.IOException; import java.time.Instant; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; @Service public class ProfileImageCleanupService{private final ProfileImageStorage storage;private final TarefaLimpezaArquivoRepository tasks;public ProfileImageCleanupService(ProfileImageStorage s,TarefaLimpezaArquivoRepository t){storage=s;tasks=t;}@Transactional(propagation=Propagation.REQUIRES_NEW)public void enqueue(String key,String reason){tasks.save(new TarefaLimpezaArquivo(key,reason));}@Scheduled(fixedDelayString="${app.profile-images.cleanup-delay:PT1M}")@Transactional public void retry(){for(var task:tasks.findTop50ByConcluidaIsNullAndProximaLessThanEqualOrderById(Instant.now()))try{storage.delete(task.getChave());task.concluir();}catch(IOException e){task.falhar(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}}}
